// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.sail.lmdb.AdjacencyEngagementTestAccess;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.benchmark.ThreeTierParityCorpus.Dataset;
import org.eclipse.rdf4j.sail.lmdb.benchmark.ThreeTierParityFixtures.Fixture;
import org.eclipse.rdf4j.sail.lmdb.evaluation.JaninoPipelineTestAccess;
import org.eclipse.rdf4j.sail.lmdb.evaluation.JoinDispatchTestAccess;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.openjdk.jmh.annotations.Benchmark;

/**
 * The engagement witness of the three-tier parity harness (ExecPlan: {@code .agent/three-tier-parity-execplan.md},
 * Milestone 0).
 *
 * <p>
 * Scores alone cannot prove the plan's ordering claim, because a higher tier is allowed to <em>decline</em> a shape and
 * fall back to the tier below: that yields equal timings, which satisfies "never slower", but it must not be mistaken
 * for the higher tier winning. This census answers the other half of the question — <em>which tier actually served each
 * query</em> — by running the whole {@link ThreeTierParityCorpus} once per regime and reading the engagement counters
 * around each execution.
 *
 * <p>
 * What it asserts:
 *
 * <ol>
 * <li>Every corpus query returns the same number of rows in all three regimes. A regime switch must never change
 * results, so this is the correctness floor of the whole plan.</li>
 * <li>In the LMDB-cursor regime no adjacency index exists and no query records adjacency engagement. This proves the
 * regime switch really does isolate the bottom tier, rather than quietly measuring adjacency three times.</li>
 * <li>In the adjacency regime, every cell listed in {@link #ADJACENCY_SERVED} engages the planes, and in the Janino
 * regime every cell listed in {@link #KERNEL_SERVED} activates a generated kernel. Those two lists are the recorded
 * baseline: a shape that serves today must not silently stop serving tomorrow.</li>
 * </ol>
 *
 * <p>
 * The census prints the full per-cell table to standard output (captured in the Surefire report), which is where the
 * plan's baseline coverage numbers come from.
 */
class ThreeTierEngagementCensusTest {

	/**
	 * Opt-in switch for the theme half of the census. The theme cells open the shared multi-gigabyte store that
	 * {@link ThemeQueryBenchmark} loads and wait for a full adjacency build over it. Measured cost of the whole
	 * three-regime theme pass is about 30 seconds, so the reason it stays opt-in is not the clock: it is that the store
	 * has to exist and match its fingerprint, and a default test run must not fail on a machine that has never loaded
	 * it. Enable with {@code -Drdf4j.lmdb.threeTierParity.themeCensus.enabled=true}.
	 */
	static final String THEME_CENSUS_PROPERTY = "rdf4j.lmdb.threeTierParity.themeCensus.enabled";

	/**
	 * Reduced dataset scale for the census. It only has to make every shape execute and engage; the timing scale that
	 * matters for the ordering claim lives in {@link ThreeTierParityBenchmark}, which keeps the benchmark defaults.
	 */
	private static final String CENSUS_FOAF_PEOPLE = "600";
	private static final String CENSUS_CORRELATED_OUTER_ROWS = "200";

	/**
	 * Cells the adjacency tier is known to serve today, recorded from the baseline census run of 2026-08-04: every
	 * generated-dataset cell except the {@code <s> ?p ?o} node edge dump, which the paged adjacency base cannot answer
	 * and which the plan deliberately leaves declining to LMDB.
	 *
	 * <p>
	 * The theme cells are absent because the theme half of the census is opt-in and has no recorded baseline yet.
	 */
	private static final Set<ThreeTierParityCorpus> ADJACENCY_SERVED = adjacencyServedBaseline();

	/**
	 * Cells the Janino tier is known to compile and serve today, recorded from the same baseline run. The notable
	 * absence is the whole cyclic family — {@code cycle3}, {@code cycle4}, {@code cycle5} and four of their variants
	 * decline to the interpreted leapfrog because kernels have no intersection primitive wired up, which is exactly
	 * what Milestone 9 addresses. Scans, point lookups and single-predicate aggregates decline too: Milestones 7 and
	 * 10.
	 */
	private static final Set<ThreeTierParityCorpus> KERNEL_SERVED = EnumSet.of(
			ThreeTierParityCorpus.TWO_HOP_FROM_SEED,
			ThreeTierParityCorpus.SELECTIVE_SIP_CHAIN,
			ThreeTierParityCorpus.DENSE_SIP_CHAIN,
			ThreeTierParityCorpus.STAR_JOIN,
			ThreeTierParityCorpus.CHAIN_JOIN_OPEN,
			ThreeTierParityCorpus.VALUES_BATCH_LOOKUP,
			ThreeTierParityCorpus.CYCLE3_GROUPED_INTEREST,
			ThreeTierParityCorpus.OPTIONAL_HEAVY,
			ThreeTierParityCorpus.MINUS_SHAPE,
			ThreeTierParityCorpus.SEQUENCE_PATH,
			ThreeTierParityCorpus.OUTER_ACCUMULATE,
			ThreeTierParityCorpus.CORRELATED_COUNT,
			ThreeTierParityCorpus.PATH_UNDER_JOIN);

	private static Set<ThreeTierParityCorpus> adjacencyServedBaseline() {
		Set<ThreeTierParityCorpus> served = EnumSet.noneOf(ThreeTierParityCorpus.class);
		served.addAll(ThreeTierParityCorpus.of(Dataset.FOAF));
		served.addAll(ThreeTierParityCorpus.of(Dataset.CORRELATED));
		served.remove(ThreeTierParityCorpus.NODE_EDGE_DUMP);
		return served;
	}

	private static final List<String> CENSUS_PROPERTIES = List.of(
			ThreeTierRegime.NATIVE_ENGINE_PROPERTY,
			ThreeTierRegime.JANINO_ENABLED_PROPERTY,
			ThreeTierRegime.JANINO_THRESHOLD_ROWS_PROPERTY,
			ConfigUtil.DIRECT_ADJACENCY_MODE_PROPERTY,
			ThreeTierParityFixtures.FOAF_PEOPLE_PROPERTY,
			ThreeTierParityFixtures.CORRELATED_OUTER_ROWS_PROPERTY);

	/**
	 * Every corpus cell must be measured by a {@code @Benchmark} method of the same name, and every such method must
	 * map back to a cell. {@code ThreeTierParityCorpus.byBenchmarkMethod} already fails a benchmark method that has no
	 * cell, but the opposite direction — a cell that no benchmark method measures — would otherwise be a silent hole in
	 * the matrix: the census would report the shape as covered while no score was ever produced for it.
	 */
	@Test
	void everyCorpusCellHasABenchmarkMethod() {
		Set<String> benchmarkMethods = new HashSet<>();
		for (Method method : ThreeTierParityBenchmark.class.getDeclaredMethods()) {
			if (method.isAnnotationPresent(Benchmark.class)) {
				benchmarkMethods.add(method.getName());
			}
		}
		List<String> missing = new ArrayList<>();
		for (ThreeTierParityCorpus cell : ThreeTierParityCorpus.values()) {
			if (!benchmarkMethods.remove(cell.benchmarkMethodName())) {
				missing.add(cell.benchmarkMethodName());
			}
		}
		assertTrue(missing.isEmpty(), "corpus cells with no @Benchmark method in ThreeTierParityBenchmark: " + missing);
		assertTrue(benchmarkMethods.isEmpty(), "@Benchmark methods with no corpus cell: " + benchmarkMethods);
		assertEquals(ThreeTierParityCorpus.values().length,
				ThreeTierParityCorpus.of(Dataset.FOAF).size()
						+ ThreeTierParityCorpus.of(Dataset.CORRELATED).size()
						+ ThreeTierParityCorpus.of(Dataset.THEME).size(),
				"every cell must belong to exactly one dataset");
	}

	@Test
	void generatedDatasetCellsEngageTheTiersTheyClaim() {
		census("FOAF + CORRELATED", List.of(Dataset.FOAF, Dataset.CORRELATED));
	}

	@Test
	@EnabledIfSystemProperty(named = THEME_CENSUS_PROPERTY, matches = "(?i)true")
	void themeCellsEngageTheTiersTheyClaim() {
		census("THEME", List.of(Dataset.THEME));
	}

	private void census(String label, List<Dataset> datasets) {
		Map<String, String> previous = new LinkedHashMap<>();
		CENSUS_PROPERTIES.forEach(property -> previous.put(property, System.getProperty(property)));
		System.setProperty(ThreeTierParityFixtures.FOAF_PEOPLE_PROPERTY, CENSUS_FOAF_PEOPLE);
		System.setProperty(ThreeTierParityFixtures.CORRELATED_OUTER_ROWS_PROPERTY, CENSUS_CORRELATED_OUTER_ROWS);

		List<ThreeTierParityCorpus> cells = new ArrayList<>();
		datasets.forEach(dataset -> cells.addAll(ThreeTierParityCorpus.of(dataset)));

		Map<ThreeTierRegime, Map<ThreeTierParityCorpus, Observation>> observations = new EnumMap<>(
				ThreeTierRegime.class);
		try {
			// Ladder order matters: the LMDB pass must run before any kernel has ever been compiled in this JVM, and
			// the Janino pass last, so a compiled kernel cannot leak backwards into a lower regime's observations.
			for (ThreeTierRegime regime : ThreeTierRegime.values()) {
				observations.put(regime, observe(regime, datasets, cells));
			}
		} finally {
			ThreeTierRegime.restore(previous);
		}

		print(label, cells, observations);
		assertRowCountParity(cells, observations);
		assertLmdbRegimeIsAdjacencyFree(cells, observations);
		assertRecordedServiceHolds(cells, observations);
	}

	/** Runs every cell once under one regime and records the engagement deltas around each execution. */
	private Map<ThreeTierParityCorpus, Observation> observe(ThreeTierRegime regime, List<Dataset> datasets,
			List<ThreeTierParityCorpus> cells) {
		Map<Dataset, Fixture> fixtures = new EnumMap<>(Dataset.class);
		Map<ThreeTierParityCorpus, Observation> observed = new EnumMap<>(ThreeTierParityCorpus.class);
		try {
			datasets.forEach(dataset -> fixtures.put(dataset, ThreeTierParityFixtures.openIsolated(dataset, regime)));
			for (ThreeTierParityCorpus cell : cells) {
				Fixture fixture = fixtures.get(cell.dataset());
				LmdbStore store = fixture.store();
				// Warm first (and, in the Janino regime, wait for compilation) so the counted execution reflects the
				// steady state of the regime rather than one-time planning and compilation work.
				fixture.prepare(cell);

				long adjacencyBefore = adjacency(store);
				long kernelViewsBefore = AdjacencyEngagementTestAccess.kernelViewsServed();
				long kernelOpensBefore = kernelOpens();

				long rows = fixture.execute(cell);

				observed.put(cell, new Observation(rows,
						adjacency(store) - adjacencyBefore,
						AdjacencyEngagementTestAccess.kernelViewsServed() - kernelViewsBefore,
						kernelOpens() - kernelOpensBefore,
						AdjacencyEngagementTestAccess.adjacencyPresent(store)));
			}
		} finally {
			fixtures.values().forEach(Fixture::close);
		}
		return observed;
	}

	private static long adjacency(LmdbStore store) {
		return AdjacencyEngagementTestAccess.lookupHits(store)
				+ AdjacencyEngagementTestAccess.exactMisses(store)
				+ AdjacencyEngagementTestAccess.plannerStatsHits(store);
	}

	/**
	 * Every generated-kernel entry point: the two general IR rungs plus the older hand-written pipeline and aggregate
	 * kernels. All four are "the Janino tier engaged", and leaving the aggregate rung out would mis-report grouped and
	 * counted shapes as declining when in fact they compile.
	 */
	private static long kernelOpens() {
		return JaninoPipelineTestAccess.openedAny() + JoinDispatchTestAccess.janinoAggregateOpened();
	}

	private void assertRowCountParity(List<ThreeTierParityCorpus> cells,
			Map<ThreeTierRegime, Map<ThreeTierParityCorpus, Observation>> observations) {
		for (ThreeTierParityCorpus cell : cells) {
			long expected = observations.get(ThreeTierRegime.LMDB).get(cell).rows();
			for (ThreeTierRegime regime : ThreeTierRegime.values()) {
				assertEquals(expected, observations.get(regime).get(cell).rows(),
						cell.benchmarkMethodName() + ": the " + regime
								+ " regime must return the same rows as the LMDB-cursor regime");
			}
		}
	}

	private void assertLmdbRegimeIsAdjacencyFree(List<ThreeTierParityCorpus> cells,
			Map<ThreeTierRegime, Map<ThreeTierParityCorpus, Observation>> observations) {
		for (ThreeTierParityCorpus cell : cells) {
			Observation observation = observations.get(ThreeTierRegime.LMDB).get(cell);
			assertFalse(observation.adjacencyPresent(),
					cell.benchmarkMethodName() + ": the LMDB-cursor regime must not build an adjacency index");
			assertEquals(0L, observation.adjacencyDelta(),
					cell.benchmarkMethodName() + ": the LMDB-cursor regime must record no adjacency engagement");
			assertEquals(0L, observation.kernelViewDelta(),
					cell.benchmarkMethodName() + ": the LMDB-cursor regime must hand no adjacency view to a kernel");
			assertEquals(0L, observation.kernelOpenDelta(),
					cell.benchmarkMethodName() + ": the LMDB-cursor regime must not open a generated kernel");
		}
	}

	private void assertRecordedServiceHolds(List<ThreeTierParityCorpus> cells,
			Map<ThreeTierRegime, Map<ThreeTierParityCorpus, Observation>> observations) {
		for (ThreeTierParityCorpus cell : cells) {
			if (ADJACENCY_SERVED.contains(cell)) {
				assertTrue(observations.get(ThreeTierRegime.ADJACENCY).get(cell).servedByAdjacency(),
						cell.benchmarkMethodName() + " used to be served from the adjacency planes and no longer is");
			}
			if (KERNEL_SERVED.contains(cell)) {
				assertTrue(observations.get(ThreeTierRegime.JANINO).get(cell).servedByKernel(),
						cell.benchmarkMethodName() + " used to compile to a Janino kernel and no longer does");
			}
		}
		assertTrue(cells.stream()
				.anyMatch(cell -> observations.get(ThreeTierRegime.ADJACENCY).get(cell).servedByAdjacency()),
				"no corpus cell engaged the adjacency planes at all, so the adjacency regime is not being measured");
		assertTrue(cells.stream()
				.anyMatch(cell -> observations.get(ThreeTierRegime.JANINO).get(cell).servedByKernel()),
				"no corpus cell activated a generated kernel, so the Janino regime is not being measured");
	}

	private void print(String label, List<ThreeTierParityCorpus> cells,
			Map<ThreeTierRegime, Map<ThreeTierParityCorpus, Observation>> observations) {
		System.out.printf("%n=== three-tier engagement census: %s ===%n", label);
		System.out.printf("%-38s %10s %10s %10s %10s %10s %10s  %s%n",
				"cell", "rows", "adj:planes", "adj:views", "jan:planes", "jan:views", "jan:kernels", "served by");
		for (ThreeTierParityCorpus cell : cells) {
			Observation adjacency = observations.get(ThreeTierRegime.ADJACENCY).get(cell);
			Observation janino = observations.get(ThreeTierRegime.JANINO).get(cell);
			List<String> servedBy = new ArrayList<>();
			if (adjacency.servedByAdjacency()) {
				servedBy.add("adjacency");
			}
			if (janino.servedByKernel()) {
				servedBy.add("janino");
			}
			System.out.printf("%-38s %10d %10d %10d %10d %10d %10d  %s%n",
					cell.benchmarkMethodName(), adjacency.rows(),
					adjacency.adjacencyDelta(), adjacency.kernelViewDelta(),
					janino.adjacencyDelta(), janino.kernelViewDelta(), janino.kernelOpenDelta(),
					servedBy.isEmpty() ? "lmdb only" : String.join("+", servedBy));
		}
	}

	/** Engagement counters observed around one execution of one cell under one regime. */
	private record Observation(long rows, long adjacencyDelta, long kernelViewDelta, long kernelOpenDelta,
			boolean adjacencyPresent) {

		boolean servedByAdjacency() {
			return adjacencyDelta > 0 || kernelViewDelta > 0;
		}

		boolean servedByKernel() {
			return kernelOpenDelta > 0;
		}
	}
}
